//! Shared helpers for adit-media integration tests.
//! Fixtures are generated by running the `ffmpeg` binary directly (never the crate under test).
//! Expected values come from the fixture recipes and SPEC arithmetic, never from adit-media.
#![allow(dead_code)]

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::mpsc;
use std::time::Duration;

use adit_media::Frame;

/// SPEC notation `s`.
pub const S: i64 = 705_600_000;

/// Start of frame `n` at 30 fps: floor(n * s / 30).
pub fn t30(n: i64) -> i64 {
    n * 23_520_000
}

/// Start of frame `n` at 30000/1001 fps: floor(n * s * 1001 / 30000) (SPEC Q4).
pub fn t2997(n: i64) -> i64 {
    assert!(n >= 0);
    n * S * 1001 / 30000
}

// ---------------------------------------------------------------- temp dirs

static COUNTER: AtomicU64 = AtomicU64::new(0);

/// Unique per-test directory, removed on drop.
pub struct TempDir(PathBuf);

impl TempDir {
    pub fn new(tag: &str) -> Self {
        let n = COUNTER.fetch_add(1, Ordering::SeqCst);
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .subsec_nanos();
        let p = std::env::temp_dir().join(format!(
            "adit-media-test-{tag}-{}-{n}-{nanos}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&p);
        std::fs::create_dir_all(&p).unwrap();
        TempDir(p)
    }
    pub fn path(&self) -> &Path {
        &self.0
    }
    /// Path of a file inside the dir, as the `&str`-style String the API takes.
    pub fn file(&self, name: &str) -> String {
        self.0.join(name).to_str().unwrap().to_string()
    }
    /// Subdirectory whose name has a space and non-ASCII characters (M-PROC-1).
    pub fn unicode_subdir(&self) -> PathBuf {
        let p = self.0.join("dir with space ü");
        std::fs::create_dir_all(&p).unwrap();
        p
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        // ffmpeg may still release handles for a moment on Windows: retry briefly.
        for _ in 0..20 {
            if std::fs::remove_dir_all(&self.0).is_ok() || !self.0.exists() {
                return;
            }
            std::thread::sleep(Duration::from_millis(100));
        }
    }
}

pub fn s(p: &Path) -> String {
    p.to_str().unwrap().to_string()
}

// ---------------------------------------------------------------- hang guard

/// Runs `f` on a thread; a hang longer than `secs` fails the test instead of blocking the run.
pub fn timed<T: Send + 'static>(secs: u64, f: impl FnOnce() -> T + Send + 'static) -> T {
    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(f));
        let _ = tx.send(r);
    });
    match rx.recv_timeout(Duration::from_secs(secs)) {
        Ok(Ok(v)) => v,
        Ok(Err(p)) => std::panic::resume_unwind(p),
        Err(_) => panic!("test hung: no result after {secs} s"),
    }
}

// ---------------------------------------------------------------- ffmpeg / ffprobe

/// Runs `ffmpeg -hide_banner -loglevel error -y <args>`; panics with stderr on failure.
pub fn ffmpeg(args: &[&str]) {
    let out = Command::new("ffmpeg")
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        .args(args)
        .output()
        .expect("ffmpeg must be on PATH");
    assert!(
        out.status.success(),
        "fixture ffmpeg {:?} failed: {}",
        args,
        String::from_utf8_lossy(&out.stderr)
    );
}

/// `ffprobe -v error <args>` stdout.
pub fn ffprobe(args: &[&str]) -> String {
    let out = Command::new("ffprobe")
        .args(["-v", "error"])
        .args(args)
        .output()
        .expect("ffprobe must be on PATH");
    assert!(
        out.status.success(),
        "ffprobe {:?} failed: {}",
        args,
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8_lossy(&out.stdout).into_owned()
}

/// key=value entries of the first video stream, with frames counted by decoding.
pub fn probe_video_stream(path: &str) -> HashMap<String, String> {
    let out = ffprobe(&[
        "-count_frames",
        "-select_streams",
        "v:0",
        "-show_entries",
        "stream=codec_name,width,height,avg_frame_rate,r_frame_rate,nb_read_frames,pix_fmt",
        "-of",
        "default=noprint_wrappers=1",
        path,
    ]);
    out.lines()
        .filter_map(|l| l.trim().split_once('='))
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect()
}

/// (codec_name, sample_rate) of every audio stream.
pub fn probe_audio_streams(path: &str) -> Vec<(String, u32)> {
    let out = ffprobe(&[
        "-select_streams",
        "a",
        "-show_entries",
        "stream=codec_name,sample_rate",
        "-of",
        "csv=p=0",
        path,
    ]);
    out.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| {
            let (c, sr) = l.trim().split_once(',').expect("codec,sample_rate");
            (c.to_string(), sr.parse().unwrap())
        })
        .collect()
}

/// Decodes video frame index `k` (0-based, decode order of presentation) with ffmpeg itself.
pub fn ffmpeg_decode_frame(path: &str, k: usize) -> Vec<u8> {
    let sel = format!("select='eq(n,{k})'");
    let out = Command::new("ffmpeg")
        .args([
            "-hide_banner",
            "-loglevel",
            "error",
            "-i",
            path,
            "-vf",
            &sel,
        ])
        .args(["-frames:v", "1", "-f", "rawvideo", "-pix_fmt", "rgba", "-"])
        .output()
        .expect("ffmpeg must be on PATH");
    assert!(
        out.status.success(),
        "decode failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    out.stdout
}

// ---------------------------------------------------------------- fixtures

/// Lossless (png-in-mov, rgb24) 64x64 clip, frame N: pixel (x, y) = (N, 4x, 4y). `frames` <= 256.
pub fn id_video(dir: &Path, name: &str, fps: &str, frames: u32) -> String {
    let p = s(&dir.join(name));
    let src = format!("nullsrc=s=64x64:r={fps},geq=r='N':g='X*4':b='Y*4'");
    let n = frames.to_string();
    ffmpeg(&[
        "-f",
        "lavfi",
        "-i",
        &src,
        "-frames:v",
        &n,
        "-c:v",
        "png",
        "-pix_fmt",
        "rgb24",
        &p,
    ]);
    p
}

/// H.264 yuv420p (qp 0) 64x64 clip, frame N is flat grey 4N. Container from `name`. `frames` <= 64.
pub fn gray_h264(dir: &Path, name: &str, fps: &str, frames: u32) -> String {
    let p = s(&dir.join(name));
    let src = format!("nullsrc=s=64x64:r={fps},geq=r='N*4':g='N*4':b='N*4'");
    let n = frames.to_string();
    ffmpeg(&[
        "-f",
        "lavfi",
        "-i",
        &src,
        "-frames:v",
        &n,
        "-c:v",
        "libx264",
        "-qp",
        "0",
        "-pix_fmt",
        "yuv420p",
        &p,
    ]);
    p
}

