/// 3 s 48000 Hz mono wav: 0.5-amplitude 440 Hz tone, silent on [gap_start, gap_end) seconds.
pub fn tone_with_gap_wav(dir: &Path, name: &str, gap_start: f64, gap_end: f64) -> String {
    let p = s(&dir.join(name));
    let expr = format!(
        "aevalsrc='if(between(t,{gap_start},{gap_end}),0,0.5*sin(2*PI*440*t))':s=48000:d=3"
    );
    ffmpeg(&["-f", "lavfi", "-i", &expr, "-c:a", "pcm_s16le", &p]);
    p
}

