// ---------------------------------------------------------------- frame checks

/// Asserts `f` is frame `n` of an `id_video` fixture, pixel-exact.
pub fn assert_id_frame(f: &Frame, n: u32) {
    assert_eq!((f.width, f.height), (64, 64));
    assert_eq!(f.rgba.len(), 64 * 64 * 4);
    for y in 0..64u32 {
        for x in 0..64u32 {
            let i = ((y * 64 + x) * 4) as usize;
            let px = &f.rgba[i..i + 4];
            assert_eq!(
                px,
                &[n as u8, (x * 4) as u8, (y * 4) as u8, 255],
                "pixel ({x},{y}): expected frame {n}, got R={} (frame number)",
                px[0]
            );
        }
    }
}

/// Frame number of a `gray_h264` fixture frame (flat grey 4N), after checking flatness and alpha.
pub fn gray_frame_number(f: &Frame) -> u32 {
    assert_eq!((f.width, f.height), (64, 64));
    assert_eq!(f.rgba.len(), 64 * 64 * 4);
    let mut sum = 0u64;
    let (mut lo, mut hi) = (255u8, 0u8);
    for px in f.rgba.chunks_exact(4) {
        assert_eq!(
            px[3], 255,
            "opaque source must decode with a = 255 (M-FRAME-4)"
        );
        sum += px[0] as u64;
        lo = lo.min(px[0]);
        hi = hi.max(px[0]);
    }
    assert!(hi - lo <= 6, "grey fixture frame not flat: {lo}..{hi}");
    let mean = sum as f64 / (64.0 * 64.0);
    (mean / 4.0).round() as u32
}

// ---------------------------------------------------------------- media builders for the encoder

pub fn flat_rgba(w: u32, h: u32, c: [u8; 4]) -> Vec<u8> {
    c.iter()
        .copied()
        .cycle()
        .take((w * h * 4) as usize)
        .collect()
}

/// Interleaved stereo 440 Hz sine, amplitude 0.3, `secs` long.
pub fn stereo_sine(sr: u32, secs: f64) -> Vec<f32> {
    let n = (sr as f64 * secs).round() as usize;
    (0..n)
        .flat_map(|i| {
            let v = 0.3 * (2.0 * std::f64::consts::PI * 440.0 * i as f64 / sr as f64).sin();
            [v as f32, v as f32]
        })
        .collect()
}
